INSERT INTO departments (id, code, name, slug, description, status, created_at, updated_at) VALUES
(1, 'TIM', 'Tim mạch', 'tim-mach', 'Khám và điều trị bệnh lý tim mạch, cao huyết áp, suy tim và rối loạn nhịp tim.', 'ACTIVE', NOW(), NOW()),
(2, 'NHI', 'Nhi khoa', 'nhi-khoa', 'Chăm sóc sức khỏe toàn diện cho trẻ em, điều trị sốt, ho, tư vấn dinh dưỡng và tiêm chủng.', 'ACTIVE', NOW(), NOW()),
(3, 'DERM', 'Da liễu', 'da-lieu', 'Điều trị các bệnh lý về da, mụn trứng cá, viêm da cơ địa, dị ứng và thẩm mỹ da.', 'ACTIVE', NOW(), NOW()),
(4, 'GEN', 'Nội tổng quát', 'noi-tong-quat', 'Khám sức khỏe tổng quát, tầm soát bệnh lý nội khoa và tư vấn sức khỏe định kỳ.', 'ACTIVE', NOW(), NOW()),
(5, 'ORTHO', 'Cơ xương khớp', 'co-xuong-khop', 'Chẩn đoán, điều trị chấn thương thể thao, thoái hóa khớp và loãng xương.', 'ACTIVE', NOW(), NOW()),
(6, 'ENT', 'Tai Mũi Họng', 'tai-mui-hong', 'Khám và điều trị viêm xoang, viêm họng, viêm tai giữa và các bệnh lý vùng mũi họng.', 'ACTIVE', NOW(), NOW()),
(7, 'OB', 'Sản phụ khoa', 'san-phu-khoa', 'Theo dõi thai kỳ trọn gói, điều trị bệnh phụ khoa và tư vấn kế hoạch hóa gia đình.', 'ACTIVE', NOW(), NOW()),
(8, 'PSY', 'Tâm thần', 'tam-than', 'Hỗ trợ và điều trị rối loạn lo âu, mất ngủ kéo dài, trầm cảm và stress.', 'ACTIVE', NOW(), NOW()),
(9, 'GI', 'Tiêu hóa', 'tieu-hoa', 'Khám điều trị đau dạ dày, trào ngược thực quản, viêm đại tràng và bệnh lý gan mật.', 'ACTIVE', NOW(), NOW()),
(10, 'RESP', 'Hô hấp', 'ho-hap', 'Điều trị viêm phế quản, hen suyễn, bệnh phổi tắc nghẽn mãn tính (COPD) và ho kéo dài.', 'ACTIVE', NOW(), NOW()),
(11, 'DENT', 'Răng Hàm Mặt', 'rang-ham-mat', 'Khám và điều trị sâu răng, viêm nướu, nhổ răng khôn và thẩm mỹ răng miệng.', 'ACTIVE', NOW(), NOW()),
(12, 'OPH', 'Mắt', 'mat', 'Đo khúc xạ, điều trị cận thị, viêm kết mạc, đục thủy tinh thể và các bệnh lý về mắt.', 'ACTIVE', NOW(), NOW()),
(13, 'NEUR', 'Thần kinh', 'than-kinh', 'Chẩn đoán rối loạn tiền đình, đau nửa đầu, đau dây thần kinh và sa sút trí tuệ.', 'ACTIVE', NOW(), NOW()),
(14, 'ENDO', 'Nội tiết', 'noi-tiet', 'Khám và điều trị đái tháo đường, bệnh lý tuyến giáp, rối loạn chuyển hóa.', 'ACTIVE', NOW(), NOW()),
(15, 'ONCO', 'Ung bướu', 'ung-buou', 'Tầm soát ung thư sớm, tư vấn và điều trị các khối u lành tính và ác tính.', 'ACTIVE', NOW(), NOW()),
(16, 'NEPH', 'Thận - Tiết niệu', 'than-tiet-nieu', 'Khám điều trị sỏi thận, viêm đường tiết niệu, suy thận và các rối loạn tiểu tiện.', 'ACTIVE', NOW(), NOW());

