('446655440001', 'TICKET-2026-0001', 'Đau ngực trái, khó thở nhẹ', 'Bệnh nhân nam 37 tuổi đau tức ngực trái khi vận động, kèm hồi hộp.', 'TRIAGED', 'URGENT', 'CRITICAL', 3, 2, 1, 1, '{"ai_confidence":0.96,"department":"Tim mach"}', '2026-05-12 08:10:00', NULL, NOW(), NOW()),
('446655440002', 'TICKET-2026-0002', 'Sốt cao ở trẻ 4 tuổi', 'Trẻ sốt 39 độ, ho nhẹ, bỏ bú và cần đánh giá Nhi khoa.', 'TRIAGED', 'URGENT', 'MAJOR', 21, 4, 2, 2, '{"ai_confidence":0.95,"department":"Nhi khoa"}', '2026-05-12 08:40:00', NULL, NOW(), NOW()),
('446655440003', 'TICKET-2026-0003', 'Phát ban ngứa kéo dài', 'Mảng đỏ ngứa xuất hiện sau khi đổi sữa rửa mặt, cần bác sĩ da liễu.', 'IN_TRIAGE', 'HIGH', 'MAJOR', 22, 5, 3, 3, '{"ai_confidence":0.89,"department":"Da lieu"}', NULL, NULL, NOW(), NOW()),
('446655440004', 'TICKET-2026-0004', 'Đau gối phải sau khi chơi bóng', 'Đau khớp gối phải, đi lại khó khăn sau chấn thương thể thao.', 'NEW', 'MEDIUM', 'MINOR', 24, 7, 5, 4, '{"ai_confidence":0.87,"department":"Co xuong khop"}', NULL, NULL, NOW(), NOW()),
('446655440005', 'TICKET-2026-0005', 'Mất ngủ, lo âu và tim đập nhanh', 'Người bệnh mất ngủ kéo dài, tim đập nhanh và căng thẳng thường xuyên.', 'TRIAGED', 'HIGH', 'MAJOR', 27, 10, 8, 6, '{"ai_confidence":0.91,"department":"Tam than"}', '2026-05-12 10:35:00', NULL, NOW(), NOW()),
('446655440006', 'TICKET-2026-0006', 'Đau họng, khàn tiếng kéo dài', 'Ho khan và đau họng gần 2 tuần, cần đánh giá Tai Mũi Họng.', 'CLOSED', 'MEDIUM', 'MINOR', 25, 8, 6, 5, '{"ai_confidence":0.86,"department":"Tai Mui Hong"}', '2026-05-12 10:10:00', NULL, NOW(), NOW()),
('446655440007', 'TICKET-2026-0007', 'Đau răng khôn hàm dưới sưng má', 'Bệnh nhân đau buốt vùng góc hàm dưới trái, sưng nướu quanh răng khôn và khó nhai.', 'TRIAGED', 'HIGH', 'MAJOR', 29, 15, 11, NULL, '{"ai_confidence":0.94,"department":"Rang Ham Mat"}', '2026-05-13 09:00:00', NULL, NOW(), NOW()),
('446655440008', 'TICKET-2026-0008', 'Đỏ mắt nhiều ghèn rỉ sau khi đi bơi', 'Mắt phải đỏ cộm, ngứa và chảy nhiều dịch rỉ vàng sau khi tắm bể bơi công cộng.', 'TRIAGED', 'MEDIUM', 'MINOR', 30, 16, 12, NULL, '{"ai_confidence":0.92,"department":"Mat"}', '2026-05-13 10:30:00', NULL, NOW(), NOW()),
('446655440009', 'TICKET-2026-0009', 'Đau nửa đầu Migraine kèm buồn nôn', 'Đau nửa đầu bên trái dội theo nhịp đập, nhạy cảm ánh sáng và tiếng động mạnh.', 'TRIAGED', 'HIGH', 'MAJOR', 31, 11, 13, NULL, '{"ai_confidence":0.95,"department":"Than kinh"}', '2026-05-13 14:15:00', NULL, NOW(), NOW()),
('446655440010', 'TICKET-2026-0010', 'Sụt cân nhanh kèm khát nước liên tục', 'Bệnh nhân sụt 5kg trong 1 tháng, khát nước liên tục và đi tiểu nhiều lần ban đêm.', 'TRIAGED', 'HIGH', 'MAJOR', 32, 17, 14, NULL, '{"ai_confidence":0.97,"department":"Noi tiet"}', '2026-05-14 08:30:00', NULL, NOW(), NOW()),
('446655440011', 'TICKET-2026-0011', 'Xuất hiện hạch cổ phải không đau', 'Sờ thấy hạch kích thước khoảng 1.5cm vùng cổ phải, di động hạn chế, không đau.', 'TRIAGED', 'HIGH', 'MAJOR', 33, 18, 15, NULL, '{"ai_confidence":0.88,"department":"Ung buou"}', '2026-05-14 11:20:00', NULL, NOW(), NOW()),
('446655440012', 'TICKET-2026-0012', 'Đau hông lưng tiểu buốt ra máu', 'Đau quặn thắt vùng lưng trái lan xuống bẹn, kèm tiểu dắt buốt và nước tiểu hồng.', 'TRIAGED', 'URGENT', 'MAJOR', 34, 19, 16, NULL, '{"ai_confidence":0.93,"department":"Than - Tiet nieu"}', '2026-05-14 15:45:00', NULL, NOW(), NOW()),
('446655440013', 'TICKET-2026-0013', 'Tăng huyết áp kèm đau đầu vùng chẩm', 'Huyết áp đo tại nhà tăng vọt lên 160/100 mmHg kèm đau nặng đầu vùng gáy, chóng mặt.', 'TRIAGED', 'HIGH', 'MAJOR', 35, 2, 1, NULL, '{"ai_confidence":0.94,"department":"Tim mach"}', '2026-05-15 08:20:00', NULL, NOW(), NOW()),
('446655440014', 'TICKET-2026-0014', 'Nổi mụn nước dạng giọt sương toàn thân', 'Trẻ 6 tuổi nổi nhiều mụn nước trong suốt, ngứa ngáy nhiều rải rác toàn thân kèm sốt nhẹ.', 'TRIAGED', 'MEDIUM', 'MINOR', 36, 4, 2, NULL, '{"ai_confidence":0.93,"department":"Nhi khoa"}', '2026-05-15 09:15:00', NULL, NOW(), NOW()),
('446655440015', 'TICKET-2026-0015', 'Mảng da đỏ vảy nến khuỷu tay gối', 'Nổi các mảng da đỏ, khô ráp, phủ đầy vảy màu trắng bạc ở vùng khuỷu tay và khớp gối.', 'TRIAGED', 'MEDIUM', 'MINOR', 37, 5, 3, NULL, '{"ai_confidence":0.91,"department":"Da lieu"}', '2026-05-15 10:45:00', NULL, NOW(), NOW()),
('446655440016', 'TICKET-2026-0016', 'Ho đờm vàng đục đau ngực khi hít thở', 'Ho nhiều đờm đặc màu vàng xanh, sốt nóng 38.8 độ, đau tức ngực phải khi ho hoặc hít sâu.', 'TRIAGED', 'HIGH', 'MAJOR', 38, 6, 4, NULL, '{"ai_confidence":0.95,"department":"Ho hap"}', '2026-05-15 14:00:00', NULL, NOW(), NOW()),
('446655440017', 'TICKET-2026-0017', 'Đau cứng khớp ngón tay hai bên vào sáng sớm', 'Đau khớp ngón tay cả hai bên, kèm cứng khớp khó co duỗi kéo dài hơn 1 tiếng mỗi sáng.', 'TRIAGED', 'MEDIUM', 'MINOR', 39, 7, 5, NULL, '{"ai_confidence":0.92,"department":"Co xuong khop"}', '2026-05-16 08:30:00', NULL, NOW(), NOW()),
('446655440018', 'TICKET-2026-0018', 'Đau tai phải chảy dịch vàng sau đợt cúm', 'Đau buốt tai phải sâu bên trong, chảy dịch đặc màu vàng đục, có sốt nhẹ và giảm thính lực.', 'TRIAGED', 'HIGH', 'MAJOR', 40, 8, 6, NULL, '{"ai_confidence":0.89,"department":"Tai Mui Hong"}', '2026-05-16 11:00:00', NULL, NOW(), NOW()),
('446655440019', 'TICKET-2026-0019', 'Thai 32 tuần phù hai chân huyết áp tăng', 'Sản phụ mang thai tuần 32 bị phù mềm hai bàn chân, huyết áp đo tại nhà 145/95 mmHg.', 'TRIAGED', 'HIGH', 'MAJOR', 41, 9, 7, NULL, '{"ai_confidence":0.94,"department":"San phu khoa"}', '2026-05-16 15:20:00', NULL, NOW(), NOW()),
('446655440020', 'TICKET-2026-0020', 'Tâm trạng buồn bã dai dẳng chán ăn mất ngủ', 'U sầu kéo dài hơn 2 tháng, mất ngủ nửa đêm về sáng, sụt 3kg, suy nghĩ tiêu cực thường xuyên.', 'TRIAGED', 'HIGH', 'MAJOR', 42, 10, 8, NULL, '{"ai_confidence":0.96,"department":"Tam than"}', '2026-05-17 09:30:00', NULL, NOW(), NOW()),
('446655440021', 'TICKET-2026-0021', 'Đau nóng rát thượng vị dữ dội sau ăn', 'Cơn đau nóng rát vùng trên rốn xuất hiện sau khi ăn đồ cay nóng, kèm đầy hơi, ợ chua.', 'TRIAGED', 'MEDIUM', 'MINOR', 43, 12, 9, NULL, '{"ai_confidence":0.95,"department":"Tieu hoa"}', '2026-05-17 14:10:00', NULL, NOW(), NOW()),
('446655440022', 'TICKET-2026-0022', 'Sốt cao đột ngột mệt mỏi nổi chấm đỏ', 'Sốt cao 39.5 độ liên tục 4 ngày không hạ, đau nhức hốc mắt và cơ khớp, xuất hiện chấm xuất huyết.', 'TRIAGED', 'URGENT', 'MAJOR', 44, 13, 10, NULL, '{"ai_confidence":0.91,"department":"Truyen nhiem"}', '2026-05-18 08:45:00', NULL, NOW(), NOW());

