(26, 44, 13, 10, '2026-05-24', '08:30:00', '09:15:00', 'COMPLETED', 'Sốt cao đột ngột ngày thứ 4 nổi ban xuất huyết.', 'Nhập viện theo dõi tiểu cầu và truyền dịch hỗ trợ.', NULL, '446655440022', NOW(), NOW());

INSERT INTO medical_records (id, appointment_id, patient_id, doctor_id, diagnosis, symptoms, treatment_plan, prescription, notes, vital_signs, follow_up_date, created_at, updated_at) VALUES
(1, 1, 3, 2, 'Cơn đau thắt ngực mức độ nhẹ, chưa ghi nhận dấu hiệu thiếu máu cơ tim cấp.', 'Đau tức ngực trái, hồi hộp, khó chịu khi leo cầu thang.', 'Nghỉ ngơi, theo dõi huyết áp tại nhà, tái khám chuyên khoa tim mạch sau 2 tuần.', 'Amlodipine 5mg nếu huyết áp tăng; nitroglycerin ngậm khi có chỉ định.', 'Khuyến cáo giảm muối và hạn chế cà phê.', '{"bp":"138/84","hr":84,"temp":36.8,"spo2":98}', '2026-05-21', NOW(), NOW()),
(2, 2, 21, 4, 'Nhiễm siêu vi đường hô hấp trên kèm sốt.', 'Sốt 39 độ, ho khan, mệt.', 'Hạ sốt khi cần, uống nhiều nước, theo dõi 48 giờ.', 'Paracetamol 250mg khi sốt trên 38.5 độ.', 'Phụ huynh cần theo dõi dấu hiệu thở nhanh.', '{"bp":"100/65","hr":112,"temp":39.1,"spo2":99}', '2026-05-12', NOW(), NOW()),
(3, 3, 22, 5, 'Viêm da tiếp xúc dị ứng.', 'Mẩn đỏ, ngứa, khô rát ở cẳng tay.', 'Ngưng sản phẩm nghi ngờ, bôi dưỡng ẩm, tránh gãi.', 'Kem hydrocortisone bôi mỏng 2 lần/ngày trong 5 ngày.', 'Nếu lan rộng cần tái khám.', '{"bp":"118/76","hr":76,"temp":36.7,"spo2":99}', '2026-05-16', NOW(), NOW()),
(4, 5, 25, 8, 'Viêm họng cấp, nghi do virus.', 'Đau họng, ho khan, khàn tiếng.', 'Nghỉ ngơi, súc họng nước muối, uống ấm.', 'Siro ho thảo dược, acetaminophen khi sốt.', 'Không kháng sinh nếu không có bằng chứng nhiễm khuẩn.', '{"bp":"110/70","hr":88,"temp":37.6,"spo2":98}', '2026-05-18', NOW(), NOW()),
(5, 10, 23, 6, 'Nhiễm siêu vi hô hấp trên nhẹ.', 'Sốt nhẹ, ho khan 3 ngày.', 'Nghỉ ngơi tại nhà, theo dõi triệu chứng.', 'Paracetamol khi cần, dung dịch súc họng.', 'Tái khám nếu sốt kéo dài quá 5 ngày.', '{"bp":"112/74","hr":90,"temp":37.8,"spo2":98}', '2026-05-20', NOW(), NOW()),
(6, 11, 29, 15, 'Viêm lợi trùm quanh răng khôn răng số 8 hàm dưới bên trái.', 'Nướu sưng đỏ đau buốt lan rộng, khó mở to miệng.', 'Vệ sinh tại chỗ bằng betadine, dùng thuốc kháng sinh giảm đau, chỉ định nhổ khi hết viêm cấp.', 'Amoxicillin 500mg + Metronidazole 250mg, Ibuprofen 400mg.', 'Súc miệng nước muối nhạt sau ăn.', '{"bp":"120/80","hr":78,"temp":37.2,"spo2":99}', '2026-05-24', NOW(), NOW()),
(7, 12, 30, 16, 'Viêm kết mạc cấp tính mắt phải.', 'Mắt phải đỏ ngầu, ngứa cộm nhiều rỉ dịch màu vàng bám quanh mi mắt.', 'Vệ sinh mắt sạch sẽ, nhỏ thuốc kháng sinh tại chỗ, tránh dụi tay lên mắt.', 'Tobrex nhỏ mắt ngày 4 lần, nước mắt nhân tạo ngày 6 lần.', 'Tránh lây nhiễm sang mắt trái và người khác.', '{"bp":"115/75","hr":72,"temp":36.5,"spo2":99}', '2026-05-22', NOW(), NOW()),
(8, 13, 31, 11, 'Hội chứng đau nửa đầu Migraine cơn điển hình.', 'Đau nửa đầu trái nhói dữ dội giật theo nhịp mạch, nôn ói nhẹ, sợ ánh sáng.', 'Nghỉ ngơi phòng tối, dùng thuốc cắt cơn sớm ngay khi chớm đau.', 'Sumpan 50mg cắt cơn khi đau dội, Magne B6 uống duy trì.', 'Tránh stress và thực phẩm có caffeine hoặc bột ngọt.', '{"bp":"118/76","hr":85,"temp":36.6,"spo2":98}', '2026-06-01', NOW(), NOW()),
(9, 14, 32, 17, 'Theo dõi đái tháo đường tuýp 2 mới phát hiện.', 'Sụt cân nhanh không rõ nguyên nhân, khát nhiều, uống nhiều, đi tiểu đêm 4-5 lần.', 'Thiết lập chế độ ăn kiêng tinh bột đường, vận động vừa sức, làm thêm nghiệm pháp dung nạp glucose.', 'Metformin 850mg ngày 1 viên sau ăn tối.', 'Theo dõi đường huyết đói mỗi sáng tại nhà.', '{"bp":"132/85","hr":80,"temp":36.8,"spo2":98}', '2026-05-25', NOW(), NOW()),
(10, 15, 33, 18, 'Hạch viêm phản ứng góc hàm cổ phải lành tính.', 'Khối hạch vùng dưới hàm phải đường kính 1.2cm di động tốt không đau đau.', 'Theo dõi định kỳ bằng siêu âm sau 1 tháng, uống thuốc tăng đề kháng.', 'Imunoglukan ngày 1 viên.', 'Tái khám ngay nếu hạch to nhanh hoặc sưng đau đỏ.', '{"bp":"122/78","hr":74,"temp":36.7,"spo2":99}', '2026-06-19', NOW(), NOW()),
(11, 16, 34, 19, 'Sỏi niệu quản trái kích thước 5mm gây ứ nước thận độ 1.', 'Đau quặn thắt hông lưng trái đột ngột dữ dội lan xuống hạ vị, tiểu buốt nhẹ.', 'Uống nhiều nước (> 2.5 lít/ngày), dùng thuốc giãn cơ trơn đường niệu để tống sỏi tự nhiên.', 'Buscopan 10mg uống khi đau, Rowatinex ngày 3 viên.', 'Vận động nhảy nhẹ gót chân hỗ trợ sỏi di chuyển.', '{"bp":"130/82","hr":92,"temp":36.9,"spo2":97}', '2026-05-26', NOW(), NOW()),
(12, 17, 35, 2, 'Tăng huyết áp vô căn độ II.', 'Đau đầu vùng gáy chẩm, chóng mặt nhẹ khi thức dậy.', 'Theo dõi huyết áp 24h, hạn chế ăn mặn, tập thể dục nhẹ nhàng.', 'Coversyl 5mg uống 1 viên sáng.', 'Nếu đau đầu tăng kèm nôn ói cần nhập viện ngay.', '{"bp":"158/96","hr":82,"temp":36.7,"spo2":98}', '2026-06-03', NOW(), NOW()),
(13, 18, 36, 4, 'Bệnh Thủy đậu biến chứng viêm da nhẹ.', 'Nốt phỏng nước rải rác toàn thân dạng giọt sương trên nền da đỏ, ngứa ngáy nhiều.', 'Bôi Xanh methylen tại các nốt phỏng vỡ, súc miệng nước ấm, cách ly tại nhà.', 'Acyclovir 400mg ngày 5 lần, siro Desloratadine giảm ngứa.', 'Không đắp lá cây lên da để tránh bội nhiễm.', '{"bp":"105/68","hr":98,"temp":37.8,"spo2":99}', '2026-05-27', NOW(), NOW()),
(14, 19, 37, 5, 'Vảy nến thể mảng thông thường.', 'Các mảng da đỏ ranh giới rõ, phủ đầy vảy da màu trắng bạc bong tróc nhiều ở cùi chỏ.', 'Bôi dưỡng ẩm tích cực hàng ngày, hạn chế cào gãi chà xát.', 'Daivobet bôi ngày 1 lần tối mỏng, sữa tắm Eucerin dưỡng ẩm.', 'Tránh stress và rượu bia chất kích thích.', '{"bp":"116/74","hr":70,"temp":36.6,"spo2":99}', '2026-06-20', NOW(), NOW()),
(15, 20, 38, 6, 'Viêm phổi thùy phải cấp tính mức độ trung bình.', 'Sốt cao run người, ho nhiều đờm đục vàng rỉ sắt, đau nhức lồng ngực bên phải.', 'Điều trị kháng sinh theo phác đồ, bù dịch đầy đủ, chụp lại X-quang kiểm tra sau 7 ngày.', 'Augmentin 1g ngày 2 viên, Acetylcysteine long đờm.', 'Uống nhiều nước ấm để loãng đờm.', '{"bp":"122/80","hr":88,"temp":38.6,"spo2":96}', '2026-05-28', NOW(), NOW()),
(16, 21, 39, 7, 'Viêm khớp dạng thấp huyết thanh dương tính tiến triển.', 'Đau sưng cứng các khớp ngón tay cả hai bên đối xứng, kéo dài hơn 1 giờ mỗi sáng.', 'Chế độ bảo vệ khớp, uống thuốc kiểm soát bệnh dài hạn dưới hướng dẫn chuyên khoa.', 'Methotrexate 10mg uống 1 lần/tuần, Acid Folic uống giãn ngày.', 'Làm kiểm tra chức năng gan thận định kỳ.', '{"bp":"124/76","hr":72,"temp":36.8,"spo2":98}', '2026-06-04', NOW(), NOW()),
(17, 22, 40, 8, 'Viêm tai giữa mủ cấp tính tai phải.', 'Đau nhức tai dội lên đầu, chảy dịch đặc đục vàng có mùi hôi từ tai phải.', 'Làm sạch ống tai thường xuyên, nhỏ kháng sinh tại chỗ, tránh để nước lọt vào tai.', 'Cefuroxime 500mg ngày 2 viên, Ofloxacin nhỏ tai ngày 3 lần.', 'Tuyệt đối không tự ý dùng tăm bông thọc sâu.', '{"bp":"118/72","hr":78,"temp":37.5,"spo2":99}', '2026-05-29', NOW(), NOW()),
(18, 23, 41, 9, 'Theo dõi tiền sản giật nhẹ trên thai 32 tuần.', 'Phù mềm ấn lõm hai bàn chân và cẳng chân dưới, huyết áp tăng nhẹ.', 'Nghỉ ngơi hoàn toàn nghiêng trái, theo dõi đạm niệu và cử động thai máy hàng ngày.', 'Dopegyt 250mg uống 2 viên chia sáng tối.', 'Tái khám ngay nếu đau đầu dữ dội, mờ mắt hoặc đau thượng vị.', '{"bp":"142/92","hr":84,"temp":36.7,"spo2":98}', '2026-05-25', NOW(), NOW()),
(19, 24, 10, 10, 'Rối loạn trầm cảm chủ yếu mức độ vừa.', 'Tâm trạng buồn bã dai dẳng, mất động lực cuộc sống, mất ngủ, chán ăn rõ rệt.', 'Trị liệu nhận thức hành vi phối hợp dùng thuốc chống trầm cảm tối thiểu 6 tháng.', 'Sertraline 50mg uống 1 viên sáng sau ăn.', 'Gia đình cần đồng hành, tránh để người bệnh cô đơn.', '{"bp":"120/78","hr":82,"temp":36.8,"spo2":98}', '2026-06-07', NOW(), NOW()),
(20, 25, 12, 11, 'Viêm loét hang vị dạ dày rải rác - Trào ngược dạ dày thực quản (GERD).', 'Cơn đau nóng rát vùng thượng vị dội lên sau ăn, ợ hơi, nóng cổ rát họng.', 'Kiêng chua cay, rượu bia, cà phê. Không nằm ngay sau khi ăn tối thiểu 2 giờ.', 'Esomeprazole 40mg uống trước ăn sáng 30 phút, Phosphalugel uống khi đau rát.', 'Nên ăn nhiều bữa nhỏ trong ngày.', '{"bp":"112/70","hr":74,"temp":36.5,"spo2":99}', '2026-06-06', NOW(), NOW()),
(21, 26, 44, 12, 'Sốt xuất huyết Dengue ngày thứ 4 có dấu hiệu cảnh báo.', 'Sốt cao liên tục khó hạ, đau nhức hốc mắt và mỏi cơ khớp sâu, xuất huyết dưới da.', 'Nhập viện theo dõi sát công thức máu và lượng tiểu cầu hàng ngày, truyền dịch ringer lactate.', 'Paracetamol 500mg uống hạ sốt khi nhiệt độ trên 38.5 (cách ít nhất 4-6 giờ).', 'Tuyệt đối cấm dùng Ibuprofen và Aspirin để hạ sốt.', '{"bp":"110/75","hr":90,"temp":39.2,"spo2":98}', '2026-05-31', NOW(), NOW());

INSERT INTO clinical_notes (id, patient_id, doctor_id, appointment_id, note_type, raw_text, file_path, file_type, extraction_status, created_at, updated_at) VALUES
(1, 3, 2, 1, 'CONSULTATION', 'Bệnh nhân trình bày đau tức ngực trái khi gắng sức. Đã tư vấn nghỉ ngơi và theo dõi dấu hiệu cảnh báo.', '/seed/notes/consult-001.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(2, 21, 4, 2, 'CONSULTATION', 'Trẻ sốt cao, khám họng thấy đỏ nhẹ, không giả mạc. Phổi phế nang đều. Theo dõi sát nhiệt độ.', '/seed/notes/consult-002.jpg', 'image', 'COMPLETED', NOW(), NOW()),
(3, 22, 5, 3, 'CONSULTATION', 'Mẩn ngứa sau khi đổi mỹ phẩm. Chẩn đoán lâm sàng dị ứng tiếp xúc da.', '/seed/notes/consult-003.png', 'image', 'COMPLETED', NOW(), NOW()),
(4, 29, 15, 11, 'CONSULTATION', 'Răng khôn 38 mọc lệch, sưng đỏ vùng lợi trùm xung quanh. Đã bơm rửa sát khuẩn bằng Betadine.', '/seed/notes/consult-004.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(5, 30, 16, 12, 'CONSULTATION', 'Kết mạc mắt phải cương tụ mạnh đỏ rực, nhiều xuất tiết dạng rỉ vàng bám quanh mi mắt.', '/seed/notes/consult-005.jpg', 'image', 'COMPLETED', NOW(), NOW()),
(6, 31, 11, 13, 'CONSULTATION', 'Bệnh nhân đau nửa đầu giật nhói. Thăm khám thần kinh chưa định vị tổn thương khu trú.', '/seed/notes/consult-006.png', 'image', 'COMPLETED', NOW(), NOW()),
(7, 32, 17, 14, 'CONSULTATION', 'Tình trạng sụt cân rõ. Xét nghiệm đường huyết mao mạch tại giường lúc đói đạt 8.2 mmol/L.', '/seed/notes/consult-007.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(8, 33, 18, 15, 'CONSULTATION', 'Siêu âm góc hàm phải có hạch lympho cấu trúc xoang hạch rõ ràng, ranh giới đều đặn.', '/seed/notes/consult-008.jpg', 'image', 'COMPLETED', NOW(), NOW()),
(9, 34, 19, 16, 'CONSULTATION', 'Cơn đau quặn thận điển hình bên trái. Siêu âm thấy sỏi niệu quản 1/3 trên kích thước 5mm.', '/seed/notes/consult-009.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(10, 35, 2, 17, 'CONSULTATION', 'Bệnh nhân có tiền sử cao huyết áp lâu năm. Đợt này đau nhức đầu chẩm gáy tăng mạnh lúc thức dậy.', '/seed/notes/consult-010.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(11, 36, 4, 18, 'CONSULTATION', 'Nhiều nốt phỏng nước rải rác toàn thân kích thước không đều, một số nốt vùng lưng đã vỡ.', '/seed/notes/consult-011.jpg', 'image', 'COMPLETED', NOW(), NOW()),
(12, 37, 5, 19, 'CONSULTATION', 'Các mảng vảy nến màu bạc xuất hiện nhiều ở khuỷu tay trái. Khám lâm sàng chưa có biểu hiện khớp.', '/seed/notes/consult-012.png', 'image', 'COMPLETED', NOW(), NOW()),
(13, 38, 6, 20, 'CONSULTATION', 'Khám phổi có rale ẩm rải rác thùy dưới phổi phải. X-quang có đám mờ không đồng đều.', '/seed/notes/consult-013.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(14, 39, 7, 21, 'CONSULTATION', 'Các khớp ngón tay 2 bên sưng đau nhẹ, sờ ấm nóng. Nghi ngờ đợt cấp viêm khớp dạng thấp.', '/seed/notes/consult-014.png', 'image', 'COMPLETED', NOW(), NOW()),
(15, 40, 8, 22, 'CONSULTATION', 'Khám nội soi tai thấy màng nhĩ tai phải phồng đỏ cộm, có dịch mủ vàng nhạt ứ đọng phía sau.', '/seed/notes/consult-015.jpg', 'image', 'COMPLETED', NOW(), NOW()),
(16, 41, 9, 23, 'CONSULTATION', 'Thai phụ mang thai 32 tuần phù chân mức độ 2. Chỉ định xét nghiệm protein niệu khẩn cấp.', '/seed/notes/consult-016.pdf', 'pdf', 'COMPLETED', NOW(), NOW()),
(17, 42, 10, 24, 'CONSULTATION', 'Bệnh nhân trầm cảm nặng buồn bã, mất ngủ trầm trọng, xuất hiện suy nghĩ tự hại bản thân.', '/seed/notes/consult-017.png', 'image', 'COMPLETED', NOW(), NOW()),
(18, 43, 12, 25, 'CONSULTATION', 'Đau nóng rát thượng vị tăng nhiều lúc đói và sau ăn đồ cay. Nghi viêm loét dạ dày tá tràng.', '/seed/notes/consult-018.jpg', 'image', 'COMPLETED', NOW(), NOW()),
(19, 44, 13, 26, 'CONSULTATION', 'Bệnh nhân sốt cao liên tục ngày 4. Đã có chấm xuất huyết dưới da cẳng tay. Chỉ định công thức máu gấp.', '/seed/notes/consult-019.pdf', 'pdf', 'COMPLETED', NOW(), NOW());
